package handlers

import (
	"testing"

	"github.com/giantswarm/mcp-toolkit/tooldesc"
	"github.com/giantswarm/mcp-toolkit/tooldesc/tooldesctest"
	"github.com/mark3labs/mcp-go/server"

	"github.com/giantswarm/mcp-capi/pkg/capi"
)

// toolsDocHeader heads docs/tools.md.
const toolsDocHeader = "# Tools\n\n" +
	"Every tool the server can offer, with its description and input schema exactly as a model reads them. " +
	"A read-only server offers only the read-only tools; capi_get_kubeconfig needs --expose-kubeconfig.\n\n" +
	"Generated by `TOOLS_DOC_UPDATE=1 go test ./pkg/mcp/handlers/ -run TestToolsDocIsCurrent`; do not edit by hand."

// newToolServer registers every tool the server can offer, with the
// annotations BuildAllTools gives them, on a fresh MCP server.
func newToolServer(t *testing.T) *server.MCPServer {
	t.Helper()
	policy := capi.WritePolicy{ExposeKubeconfig: true}
	ctx := NewCallerIdentityServerContext(capi.NewBearerClientFactory("https://kubernetes.default.svc", "", nil), policy)
	tools, err := BuildAllTools(ctx)
	if err != nil {
		t.Fatalf("BuildAllTools() error = %v", err)
	}
	s := server.NewMCPServer("mcp-capi", "test")
	for _, reg := range tools {
		s.AddTool(reg.Tool, reg.Handler)
	}
	return s
}

// TestToolDescriptions holds every description to the budget: a summary line
// muster's discovery shows whole, short descriptions and parameter texts.
func TestToolDescriptions(t *testing.T) {
	if err := tooldesc.CheckServer(newToolServer(t), tooldesc.DefaultBudget); err != nil {
		t.Fatal(err)
	}
}

// TestToolsDocIsCurrent keeps docs/tools.md equal to the registered tools.
func TestToolsDocIsCurrent(t *testing.T) {
	tooldesctest.AssertServerDoc(t, newToolServer(t), toolsDocHeader, "../../../docs/tools.md")
}
